dtsPropsFor.Ring:
/** 0-100. Clamped internally. */
  percent: number;
  /** Pre-formatted elapsed time, e.g. "4m 12s". */
  elapsed?: string;
  /** Separate from percent: a run that failed at 60% must not look like one that is 60% done. */
  tone?: "live" | "done" | "failed";
  /** Pixel diameter. Defaults to 188. */
  size?: number;

dtsPropsFor.Meter:
/** 0-100. Clamped internally. */
  percent: number;
  /** CSS colour for the fill. Defaults to var(--green). */
  hue?: string;

dtsPropsFor.Disc:
/** Leading glyph in the summary row. Defaults to a chevron. */
  glyph?: React.ReactNode;
  title: React.ReactNode;
  /** Secondary line under the title. */
  sub?: React.ReactNode;
  /** Right-aligned content in the summary row. */
  right?: React.ReactNode;
  /** Renders the native <details> expanded. */
  open?: boolean;
  children: React.ReactNode;

dtsPropsFor.Tag:
/** Framework pack short name, e.g. "NIST AI RMF". */
  pack: string;
  /** The control id within that pack, e.g. "GOVERN-1.1". */
  id: string;
